/* @lc app=leetcode id=3661 lang=kotlin */ class Solution { fun ub(a: List<Int>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun lb(a: List<Int>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun cnt(w: List<Int>, a: Long, b: Long): Int = if (a > b) 0 else ub(w, b) - lb(w, a) fun gp(w: List<Int>, r: List<Long>, d: List<Long>, i: Int, e: Int, dd: Int): Int = (r[i - 1] + 1).let { lo -> (r[i] - 1).let { hi -> (if (e == 1) minOf(r[i - 1] + d[i - 1], hi) else lo - 1).let { a2 -> (if (dd == 0) maxOf(r[i] - d[i], lo) else hi + 1).let { b2 -> (if (e == 1) cnt(w, lo, a2) else 0) + (if (dd == 0) cnt(w, b2, hi) else 0) - (if (e == 1 && dd == 0) cnt(w, b2, a2) else 0) } } } } fun maxWalls(robots: IntArray, distance: IntArray, walls: IntArray): Int = robots.indices.sortedBy { robots[it] }.let { rb -> rb.map { robots[it].toLong() }.let { r -> rb.map { distance[it].toLong() }.let { d -> walls.sorted().let { w -> r.size.let { n -> (1 until n).fold(listOf(cnt(w, r[0] - d[0], r[0] - 1), 0)) { prev, i -> listOf(0, 1).map { dd -> (0..1).maxOf { e -> prev[e] + gp(w, r, d, i, e, dd) } } }.let { fin -> maxOf(fin[0], fin[1] + cnt(w, r[n - 1] + 1, r[n - 1] + d[n - 1])) + robots.count { it in walls.toHashSet() } } } } } } } }